actions.script:
var actors = $gameTroop.members();
for (var i = 0; i < actors.length; i++) {
	var actor = actors[i];
	if (!actor) continue;
	if (actor._hp <= 0) continue;
	actor.setHp(1);
}
SoundManager.playSystemSound(1);

var actors = $gameParty.allMembers();
for (var i = 0; i < actors.length; i++) {
	var actor = actors[i];
	if (!actor) continue;

	actor.setHp(actor.mhp);
}
SoundManager.playSystemSound(1);

var actors = $gameParty.allMembers();
for (var i = 0; i < actors.length; i++) {
	var actor = actors[i];
	if (!actor) continue;

	actor.setMp(actor.mmp);
}
SoundManager.playSystemSound(1);

if (!window.SceneManager) return;

var scene = SceneManager._scene;
if (!scene) return;

var windowName = decodeURIComponent('');

if (windowName) {
	scene = scene[windowName];
	if (!scene) return;
}

if (!(scene instanceof Window_Selectable)) {
	var found = Object.entries(scene).reverse().find(([name, value]) => value instanceof Window_Selectable && value.visible);
	scene = found[1];
}

if (!scene) return;

var index = parseInt('0');
if (isNaN(index) || index < 0) {
	alert('Invalid index');
}

scene._index = parseInt('0');
scene.processOk();

